function validateUseCase(uc) {
  if (!uc.actor) return 'missing actor';
  if (!uc.steps || uc.steps.length === 0) return 'missing steps';
  if (!uc.altFlows || uc.altFlows.length === 0) return 'missing alt flows';
  return 'complete';
}
console.log(validateUseCase({ actor: 'Customer', steps: ['pay'], altFlows: ['card declined'] }));

